import{_ as a,o as t,c as s,ai as e}from"./chunks/framework.Ai2o9gNv.js";const p="/assets/image-20260611131628195.OsCgw5fb.png",E="/assets/image-20260611124024967.D9ZRWV5A.png",r="/assets/image-20260611124042426.CtlK6zJO.png",o="/assets/image-20260611124228783.dQ3fOuYh.png",i="/assets/image-20260611124252658.CMfTIIJF.png",_="/assets/image-20260611124609971.rIqK8ejU.png",m="/assets/image-20260611124656445.Qpis9lzU.png",g="/assets/image-20260611124755277.CJ50jzJM.png",l="/assets/image-20260611124827620.CFx1JIpE.png",B="/assets/image-20260611124933725.lJ7dUNmx.png",u=JSON.parse('{"title":"一封邮件，让我重新打开了搁置半年的鸿蒙应用","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/因为这一个用户，我继续更新了下鸿蒙应用的功能/因为这一个用户，我继续更新了下鸿蒙应用的功能.md","filePath":"鸿蒙开发技巧/因为这一个用户，我继续更新了下鸿蒙应用的功能/因为这一个用户，我继续更新了下鸿蒙应用的功能.md","lastUpdated":1781155042000,"__rawMarkdown":"# 一封邮件，让我重新打开了搁置半年的鸿蒙应用\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：https://blog.zbztb.cn/\\n>\\n> 2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n![](assets/image-20260611131628195.png)\\n\\n## 前言\\n\\n\\n\\n​\\t《可可图片编辑》是去年上架的一款鸿蒙应用，提供处理图片的能力，提供有图片压缩、裁剪、滤镜、水印、自由绘画和图片拼图等功能，单机版本，也是免费的。\\n\\n![](assets/image-20260611124024967.png)\\n\\n​\\t上架之后，万少本身也希望分享知识，也将这个应用做成教程分享出去了。\\n\\n> 博客地址\\n>\\n> https://blog.zbztb.cn/%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91%E6%8A%80%E5%B7%A7/%E5%8F%AF%E5%8F%AF%E5%9B%BE%E7%89%87%E7%BC%96%E8%BE%91/%E5%8F%AF%E5%8F%AF%E5%9B%BE%E7%89%87%E7%BC%96%E8%BE%91%20HarmonyOS%EF%BC%882%EF%BC%89%20%E9%80%89%E6%8B%A9%E5%9B%BE%E7%89%87/%E5%8F%AF%E5%8F%AF%E5%9B%BE%E7%89%87%E7%BC%96%E8%BE%91%20HarmonyOS%EF%BC%882%EF%BC%89%20%E9%80%89%E6%8B%A9%E5%9B%BE%E7%89%87.html\\n\\n![](assets/image-20260611124042426.png)\\n\\n--\\n\\n上线后，修复了几个小功能，后面没有怎么管过用户量，只是在应用内保留个联系方式。\\n\\n![](assets/image-20260611124228783.png)\\n\\n---\\n\\n![](assets/image-20260611124252658.png)\\n\\n## 起源\\n\\n​\\t因为维护一个产品其实一直都要花费不少时间的，本身万少也是身边有很多的事要忙，分析报告说有了AI之后，其实时间并没有减少，相反的你可能会主动做更多的事情。\\n\\n​\\t回到正题上，但是比较有意思的是，确实会有真实的用户通过邮件反馈我这个应用的建议。\\n\\n---\\n\\n![image-20260611124609971](assets/image-20260611124609971.png)\\n\\n---\\n\\n本来只是提供了单张图片的压缩，经过反馈后，添加了批量上传图片压缩（9张）\\n\\n![](assets/image-20260611124656445.png)\\n\\n---\\n\\n后面继续反馈，可以添加更多张图片压缩。\\n\\n![](assets/image-20260611124755277.png)\\n\\n---\\n\\n后面拖了很久，今天也终于抽空处理了下。\\n\\n![](assets/image-20260611124827620.png)\\n\\n功能不太难，但是打开工具、编辑、测试、发布上线，其实再怎么样也要1个小时的时间了。\\n\\n不过自己的努力可以得到一些认可的话，也是很不错的。\\n\\n## 附带应用的截图\\n\\n\\n\\n![](assets/image-20260611124933725.png)\\n\\n## 最近\\n\\n最近也在处理鸿蒙的端云一体的项目，其实之前已经更新了一款《奇趣故事匣》，这个全部是鸿蒙能力，包括后端，后续也会免费分享出来。\\n\\n而现在是在重构 《朋友圈文案》，它只是是使用传统的后端能力，我感觉部署维护麻烦，这次也是想要切换到鸿蒙的端云一体上，用上云数据库、云函数、云托管。\\n\\n最后打通鸿蒙端的一些支付能力，作为程序员，技术工作者，做出可以持续盈利的应用，我想应该是很多同行的想法。\\n\\n目前有了AI能力的加持，可以减少了很多工作，但是大部分鸿蒙端的开发者都是偏向前端，后端的逻辑、运维都不太理解，因此我\\n\\n希望走通这些流程，然后分享给其他人，希望所有的鸿蒙开发者都可以通过鸿蒙的能力+自身的技术实现价值。"}'),c={name:"鸿蒙开发技巧/因为这一个用户，我继续更新了下鸿蒙应用的功能/因为这一个用户，我继续更新了下鸿蒙应用的功能.md"};function h(F,n,b,d,A,C){return t(),s("div",null,[...n[0]||(n[0]=[e('<h1 id="一封邮件-让我重新打开了搁置半年的鸿蒙应用" tabindex="-1">一封邮件，让我重新打开了搁置半年的鸿蒙应用 <a class="header-anchor" href="#一封邮件-让我重新打开了搁置半年的鸿蒙应用" aria-label="Permalink to &quot;一封邮件，让我重新打开了搁置半年的鸿蒙应用&quot;">​</a></h1><blockquote><p>万少：华为HDE、鸿蒙极客</p><p>个人主页：<a href="https://blog.zbztb.cn/" target="_blank" rel="noreferrer">https://blog.zbztb.cn/</a></p><p>2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。</p><p>如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。</p></blockquote><p><img src="'+p+'" alt=""></p><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>​ 《可可图片编辑》是去年上架的一款鸿蒙应用，提供处理图片的能力，提供有图片压缩、裁剪、滤镜、水印、自由绘画和图片拼图等功能，单机版本，也是免费的。</p><p><img src="'+E+'" alt=""></p><p>​ 上架之后，万少本身也希望分享知识，也将这个应用做成教程分享出去了。</p><blockquote><p>博客地址</p><p><a href="https://blog.zbztb.cn/%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91%E6%8A%80%E5%B7%A7/%E5%8F%AF%E5%8F%AF%E5%9B%BE%E7%89%87%E7%BC%96%E8%BE%91/%E5%8F%AF%E5%8F%AF%E5%9B%BE%E7%89%87%E7%BC%96%E8%BE%91%20HarmonyOS%EF%BC%882%EF%BC%89%20%E9%80%89%E6%8B%A9%E5%9B%BE%E7%89%87/%E5%8F%AF%E5%8F%AF%E5%9B%BE%E7%89%87%E7%BC%96%E8%BE%91%20HarmonyOS%EF%BC%882%EF%BC%89%20%E9%80%89%E6%8B%A9%E5%9B%BE%E7%89%87.html" target="_blank" rel="noreferrer">https://blog.zbztb.cn/鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（2） 选择图片/可可图片编辑 HarmonyOS（2） 选择图片.html</a></p></blockquote><p><img src="'+r+'" alt=""></p><p>--</p><p>上线后，修复了几个小功能，后面没有怎么管过用户量，只是在应用内保留个联系方式。</p><p><img src="'+o+'" alt=""></p><hr><p><img src="'+i+'" alt=""></p><h2 id="起源" tabindex="-1">起源 <a class="header-anchor" href="#起源" aria-label="Permalink to &quot;起源&quot;">​</a></h2><p>​ 因为维护一个产品其实一直都要花费不少时间的，本身万少也是身边有很多的事要忙，分析报告说有了AI之后，其实时间并没有减少，相反的你可能会主动做更多的事情。</p><p>​ 回到正题上，但是比较有意思的是，确实会有真实的用户通过邮件反馈我这个应用的建议。</p><hr><p><img src="'+_+'" alt="image-20260611124609971"></p><hr><p>本来只是提供了单张图片的压缩，经过反馈后，添加了批量上传图片压缩（9张）</p><p><img src="'+m+'" alt=""></p><hr><p>后面继续反馈，可以添加更多张图片压缩。</p><p><img src="'+g+'" alt=""></p><hr><p>后面拖了很久，今天也终于抽空处理了下。</p><p><img src="'+l+'" alt=""></p><p>功能不太难，但是打开工具、编辑、测试、发布上线，其实再怎么样也要1个小时的时间了。</p><p>不过自己的努力可以得到一些认可的话，也是很不错的。</p><h2 id="附带应用的截图" tabindex="-1">附带应用的截图 <a class="header-anchor" href="#附带应用的截图" aria-label="Permalink to &quot;附带应用的截图&quot;">​</a></h2><p><img src="'+B+'" alt=""></p><h2 id="最近" tabindex="-1">最近 <a class="header-anchor" href="#最近" aria-label="Permalink to &quot;最近&quot;">​</a></h2><p>最近也在处理鸿蒙的端云一体的项目，其实之前已经更新了一款《奇趣故事匣》，这个全部是鸿蒙能力，包括后端，后续也会免费分享出来。</p><p>而现在是在重构 《朋友圈文案》，它只是是使用传统的后端能力，我感觉部署维护麻烦，这次也是想要切换到鸿蒙的端云一体上，用上云数据库、云函数、云托管。</p><p>最后打通鸿蒙端的一些支付能力，作为程序员，技术工作者，做出可以持续盈利的应用，我想应该是很多同行的想法。</p><p>目前有了AI能力的加持，可以减少了很多工作，但是大部分鸿蒙端的开发者都是偏向前端，后端的逻辑、运维都不太理解，因此我</p><p>希望走通这些流程，然后分享给其他人，希望所有的鸿蒙开发者都可以通过鸿蒙的能力+自身的技术实现价值。</p>',38)])])}const q=a(c,[["render",h]]);export{u as __pageData,q as default};
